    / Define the ordered list of planets
    planets:`Mercury`Venus`Earth`Mars`Jupiter`Saturn`Uranus`Neptune;

    / Convert inputs to symbols for efficient lookup
    sx:xsym x; 
    sy:xsym y;

    / Find positions of the provided planets in the list
    / pos will be null if the planet name is not found
    px:pos:planets where planets = sx;
    py:pos:planets where planets = sy;

    / Return empty list if either planet is not in the list
    if[null px or null py; :()]

    / Determine the start and end indices for the slice
    / We use min/max to handle cases where planet2 is closer to the sun than planet1
    start:min[px;py] + 1;
    end:max[px;py] - 1;

    / If start > end, there are no planets in between
    if[start > end; :()]

    / Slice the list, convert symbols back to strings, and return as a list
    ($) planets start end
    }
